export const getViewOfficialAccountClaimConfirmationUrl = (params: ViewOfficialAccountClaimConfirmationParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/auth/official-claim/verify?${stringifiedParams}` : `/api/auth/official-claim/verify`
}

